    // acquisition; that release disposes only after the settlement barrier.
    const hold = (acquire: () => unknown, release: () => void) => Effect.zipRight(
      Effect.addFinalizer(() => Effect.zipRight(settled(lifetime), Effect.sync(release))),
      attemptSync(acquire),
    );
